// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    Signer maker;
    FakeERC20 token;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        maker = new Signer();
        token = new FakeERC20();
    }

    function testFuzz_property(uint256 premium, uint256 feeRate, address recipient) public {
        vm.assume(recipient != address(0));
        premium = bound(premium, 1, 1e30);
        feeRate = bound(feeRate, 1, 29);

        c.setFee(feeRate);

        address[] memory emptyAddrs = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: false,
            isLong: true,
            baseAsset: address(token),
            strike: 0,
            premium: premium,
            duration: 1 days,
            expiration: block.timestamp + 1 days,
            nonce: 0,
            whitelist: emptyAddrs,
            floorTokens: emptyAddrs,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes memory sig = new bytes(0);
        uint256[] memory floorIds = new uint256[](0);

        c.fillOrder(order, sig, floorIds);

        uint256 accrued = c.unclaimedFees(address(token));
        assertTrue(accrued == (premium * feeRate) / 1000, "fees accrued as expected");

        c.withdrawFees(address(token), recipient);

        // General rule: after withdrawFees completes, the unclaimed fees for the
        // asset are fully consumed — the counter is zeroed — so fees can never
        // be withdrawn twice.
        assertTrue(c.unclaimedFees(address(token)) == 0, "unclaimed fees must be zero after withdrawal");
    }
}

contract Signer {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }
}

contract FakeERC20 {
    mapping(address => uint256) public balanceOf;

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[to] += amount;
        return true;
    }

    function transferFrom(address, address to, uint256 amount) external returns (bool) {
        balanceOf[to] += amount;
        return true;
    }

    function approve(address, uint256) external returns (bool) {
        return true;
    }
}
